==> features/auth/screens/ProfileScreen.tsx <==
import { useEffect, useState } from 'react';
import { ScrollView, StyleSheet } from 'react-native';
import {
  ActivityIndicator,
  Button,
  List,
  Text,
  useTheme,
} from 'react-native-paper';
import { useSession } from '@/shared/session/SessionProvider';
import { toApiError } from '@/shared/http/apiError';
import { t } from '@/shared/i18n';

/**
 * Example protected screen: only reachable while signed in. On open it
 * reloads the user from the auth backend with the stored token; if the token
 * has expired, the API's 401 signs the user out and the route guard returns
 * them to Home.
 */
export function ProfileScreen() {
  const theme = useTheme();
  const { session, signOut, refreshUser } = useSession();
  const [refreshing, setRefreshing] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const user = session.user;

  useEffect(() => {
    let active = true;
    refreshUser()
      .catch(err => {
        const apiError = toApiError(err);
        // A 401 signs out; the guard navigates away, so there is nothing to show.
        if (active && apiError.code !== 'unauthorized') {
          setError(apiError.message);
        }
      })
      .finally(() => {
        if (active) setRefreshing(false);
      });
    return () => {
      active = false;
    };
  }, [refreshUser]);

  return (
    <ScrollView
      style={{ backgroundColor: theme.colors.background }}
      contentContainerStyle={styles.content}
    >
      <Text variant="bodyMedium" style={styles.intro}>
        {t('profile.intro')}
      </Text>
      {refreshing && (
        <ActivityIndicator style={styles.status} testID="profile-refreshing" />
      )}
      {error && (
        <Text
          variant="bodyMedium"
          style={[styles.status, { color: theme.colors.error }]}
          testID="profile-error"
        >
          {t('profile.refreshFailed', { message: error })}
        </Text>
      )}
      <List.Item
        title={t('profile.name')}
        description={user?.name ?? '—'}
        left={props => <List.Icon {...props} icon="account" />}
      />
      <List.Item
        title={t('profile.email')}
        description={user?.email ?? '—'}
        left={props => <List.Icon {...props} icon="email" />}
      />
      <Button
        mode="outlined"
        onPress={signOut}
        style={styles.button}
        testID="profile-logout"
      >
        {t('home.session.logOut')}
      </Button>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  content: {
    padding: 16,
  },
  intro: {
    marginBottom: 8,
  },
  status: {
    marginVertical: 8,
  },
  button: {
    marginTop: 24,
  },
});

==> shared/storage/storage.ts <==
/**
 * Storage Service
 * AsyncStorage wrapper with JSON serialization and TypeScript support
 */
import AsyncStorage from '@react-native-async-storage/async-storage';
import { logger } from '@/shared/lib/logger';

// Common storage keys used across the app
export const STORAGE_KEYS = {
  AUTH_TOKEN: 'auth_token',
  USER_DATA: 'user_data',
} as const;

/**
 * Store a value in AsyncStorage with JSON serialization
 */
export async function setItem<T>(key: string, value: T): Promise<void> {
  try {
    const jsonValue = JSON.stringify(value);
    await AsyncStorage.setItem(key, jsonValue);
  } catch (error) {
    logger.error(`Error storing ${key}`, error);
    throw error;
  }
}

/**
 * Retrieve a value from AsyncStorage with JSON deserialization
 */
export async function getItem<T>(key: string): Promise<T | null> {
  try {
    const jsonValue = await AsyncStorage.getItem(key);
    return jsonValue != null ? (JSON.parse(jsonValue) as T) : null;
  } catch (error) {
    logger.error(`Error retrieving ${key}`, error);
    return null;
  }
}

/**
 * Remove a specific item from AsyncStorage
 */
export async function removeItem(key: string): Promise<void> {
  try {
    await AsyncStorage.removeItem(key);
  } catch (error) {
    logger.error(`Error removing ${key}`, error);
    throw error;
  }
}

