/**
 * The user's light/dark choice. Until they pick one the app follows the
 * system setting; their choice is persisted and restored on launch.
 */
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import { useColorScheme } from 'react-native';
import { z } from 'zod';
import { logger } from '@/shared/lib/logger';
import { getItem, setItem, STORAGE_KEYS } from '@/shared/storage/storage';

const themePreferenceSchema = z.enum(['system', 'light', 'dark']);

export type ThemePreference = z.infer<typeof themePreferenceSchema>;

export interface ThemePreferenceValue {
  preference: ThemePreference;
  /** The scheme in effect: the preference, or the system's when 'system'. */
  colorScheme: 'light' | 'dark';
  setPreference(preference: ThemePreference): void;
}

const ThemePreferenceContext = createContext<ThemePreferenceValue | null>(
  null
);

export function ThemePreferenceProvider({ children }: { children: ReactNode }) {
  const systemScheme = useColorScheme();
  const [preference, setPreferenceState] = useState<ThemePreference | null>(
    null
  );

  useEffect(() => {
    let active = true;
    getItem<unknown>(STORAGE_KEYS.THEME_PREFERENCE).then(stored => {
      const parsed = themePreferenceSchema.safeParse(stored);
      if (active) setPreferenceState(parsed.success ? parsed.data : 'system');
    });
    return () => {
      active = false;
    };
  }, []);

  const setPreference = useCallback((next: ThemePreference) => {
    setPreferenceState(next);
    // The choice still applies for this run if it can't be saved.
    setItem(STORAGE_KEYS.THEME_PREFERENCE, next).catch(error =>
      logger.error('Failed to save the theme preference', error)
    );
  }, []);

  const value = useMemo<ThemePreferenceValue | null>(() => {
    if (preference === null) return null;
    const colorScheme =
      preference === 'system'
        ? systemScheme === 'dark'
          ? 'dark'
          : 'light'
        : preference;
    return { preference, colorScheme, setPreference };
  }, [preference, systemScheme, setPreference]);

  // Render nothing until the stored choice is read, so the app doesn't flash
  // the system theme first; the native splash screen is still up meanwhile.
  if (value === null) return null;

  return (
    <ThemePreferenceContext.Provider value={value}>
      {children}
    </ThemePreferenceContext.Provider>
  );
}

export function useThemePreference(): ThemePreferenceValue {
  const value = useContext(ThemePreferenceContext);
  if (!value) {
    throw new Error(
      'useThemePreference must be used inside <ThemePreferenceProvider>'
    );
  }
  return value;
}

